        Some("--version") if args.len() == 1 => {
            println!("authnote 0.1.0");
            ExitCode::SUCCESS
        }
        Some("sign") => sign(&args[1..]),
        _ => {
            eprintln!("Usage: authnote --version");
            eprintln!(
                "       authnote sign --key HEX --key-id ID --key-version N [--field TEXT]..."
            );
            ExitCode::from(2)
        }
    }
}

struct SignOptions {
    key: String,
    key_id: String,
    key_version: String,
    fields: Vec<String>,
