1	//! End-to-end regression tests for the observable result of `authnote sign`.
2	//!
3	//! These tests execute the built binary and assert on the exact JSON record a
4	//! user receives on stdout/stderr, not just on intermediate HMAC values.
5	//!
6	//! Expected tags are *golden* values: each was computed independently with
7	//! Python's hmac/hashlib/struct straight from the format-1 byte contract in
8	//! README.md (domain separator `authnote-sign-v1`, big-endian u64/u32 length
9	//! prefixes, raw UTF-8 bytes), never derived from this crate's own HMAC code.
10	//! A change that breaks the byte encoding and the JSON output in the same way
11	//! therefore still fails these tests.
12	//!
13	//! The tests parse stdout with the small JSON parser below instead of pulling
14	//! in a third-party dependency, so `Cargo.toml` stays unchanged.
15	
16	use std::process::{Command, Output};
17	
18	// ---------------------------------------------------------------------------
19	// Test harness around the compiled binary.
20	// ---------------------------------------------------------------------------
21	
22	fn authnote() -> Command {
23	    Command::new(env!("CARGO_BIN_EXE_authnote"))
24	}
25	
26	/// Run `sign` with `--field` entries appended in the given order.
27	fn run_sign(key: &str, key_id: &str, version: &str, fields: &[&str]) -> Output {
28	    let mut cmd = authnote();
29	    cmd.arg("sign")
30	        .arg("--key")
31	        .arg(key)
32	        .arg("--key-id")
33	        .arg(key_id)
34	        .arg("--key-version")
35	        .arg(version);
36	    for f in fields {
37	        cmd.arg("--field").arg(f);
38	    }
39	    cmd.output().expect("failed to execute authnote")
40	}
41	
42	/// Run `sign` with a raw argument vector (for error-path cases).
43	fn run_sign_raw(args: &[&str]) -> Output {
44	    let mut cmd = authnote();
45	    cmd.arg("sign");
46	    for a in args {
47	        cmd.arg(a);
48	    }
49	    cmd.output().expect("failed to execute authnote")
50	}
51	
52	// ---------------------------------------------------------------------------
53	// Minimal JSON parser (objects, arrays, strings, integers, true/false/null).
54	// ---------------------------------------------------------------------------
55	
56	#[derive(Debug, Clone)]
57	enum Json {
58	    Null,
59	    // Retained for parser completeness; records carry no boolean values.
60	    #[allow(dead_code)]
61	    Bool(bool),
62	    Num(i64),
63	    Str(String),
64	    Arr(Vec<Json>),
65	    Obj(Vec<(String, Json)>),
66	}
67	
68	impl Json {
69	    fn parse(s: &str) -> Json {
70	        let mut p = Parser {
71	            chars: s.chars().collect(),
72	            pos: 0,
73	        };
74	        p.ws();
75	        let v = p.value();
76	        p.ws();
77	        assert_eq!(p.pos, p.chars.len(), "trailing data after JSON record: {s}");
78	        v
79	    }
80	
81	    fn as_str(&self) -> &str {
82	        match self {
83	            Json::Str(s) => s,
84	            other => panic!("expected JSON string, got {other:?}"),
85	        }
86	    }
87	
88	    fn as_i64(&self) -> i64 {
89	        match self {
90	            Json::Num(n) => *n,
91	            other => panic!("expected JSON number, got {other:?}"),
92	        }
93	    }
94	
95	    fn as_array(&self) -> &[Json] {
96	        match self {
97	            Json::Arr(a) => a,
98	            other => panic!("expected JSON array, got {other:?}"),
99	        }
100	    }
101	
102	    fn as_object(&self) -> &[(String, Json)] {
103	        match self {
104	            Json::Obj(o) => o,
105	            other => panic!("expected JSON object, got {other:?}"),
106	        }
107	    }
108	
109	    fn get(&self, key: &str) -> &Json {
110	        let obj = self.as_object();
111	        let idx = obj
112	            .iter()
113	            .position(|(k, _)| k == key)
114	            .unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"));
115	        &obj[idx].1
116	    }
117	
118	    /// Every string value anywhere in the document.
119	    fn strings(&self, out: &mut Vec<String>) {
120	        match self {
121	            Json::Str(s) => out.push(s.clone()),
122	            Json::Arr(a) => a.iter().for_each(|v| v.strings(out)),
123	            Json::Obj(o) => o.iter().for_each(|(_, v)| v.strings(out)),
124	            Json::Null | Json::Bool(_) | Json::Num(_) => {}
125	        }
126	    }
127	}
128	
129	struct Parser {
130	    chars: Vec<char>,
131	    pos: usize,
132	}
133	
134	impl Parser {
135	    fn ws(&mut self) {
136	        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
137	            self.pos += 1;
138	        }
139	    }
140	
141	    fn bump(&mut self) -> char {
142	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
143	        let c = self.chars[self.pos];
144	        self.pos += 1;
145	        c
146	    }
147	
148	    fn expect(&mut self, want: char) {
149	        assert!(self.pos < self.chars.len(), "expected {want:?}, found end of JSON");
150	        let got = self.chars[self.pos];
151	        assert_eq!(got, want, "expected {want:?} at byte {}", self.pos);
152	        self.pos += 1;
153	    }
154	
155	    fn value(&mut self) -> Json {
156	        self.ws();
157	        assert!(self.pos < self.chars.len(), "unexpected end of JSON");
158	        match self.chars[self.pos] {
159	            '{' => self.object(),
160	            '[' => self.array(),
161	            '"' => Json::Str(self.string()),
162	            't' | 'f' => self.boolean(),
163	            'n' => self.null(),
164	            c if c == '-' || c.is_ascii_digit() => self.number(),
165	            c => panic!("unexpected character {c:?} in JSON"),
166	        }
167	    }
168	
169	    fn object(&mut self) -> Json {
170	        self.expect('{');
171	        let mut entries = Vec::new();
172	        self.ws();
173	        if self.chars[self.pos] == '}' {
174	            self.pos += 1;
175	            return Json::Obj(entries);
176	        }
177	        loop {
178	            self.ws();
179	            let key = self.string();
180	            self.ws();
181	            self.expect(':');
182	            let val = self.value();
183	            entries.push((key, val));
184	            self.ws();
185	            match self.bump() {
186	                ',' => continue,
187	                '}' => break,
188	                c => panic!("bad object separator {c:?}"),
189	            }
190	        }
191	        Json::Obj(entries)
192	    }
193	
194	    fn array(&mut self) -> Json {
195	        self.expect('[');
196	        let mut items = Vec::new();
197	        self.ws();
198	        if self.chars[self.pos] == ']' {
199	            self.pos += 1;
200	            return Json::Arr(items);
201	        }
202	        loop {
203	            items.push(self.value());
204	            self.ws();
205	            match self.bump() {
206	                ',' => continue,
207	                ']' => break,
208	                c => panic!("bad array separator {c:?}"),
209	            }
210	        }
211	        Json::Arr(items)
212	    }
213	
214	    fn string(&mut self) -> String {
215	        self.expect('"');
216	        let mut out = String::new();
217	        loop {
218	            match self.bump() {
219	                '"' => break,
220	                '\\' => match self.bump() {
221	                    '"' => out.push('"'),
222	                    '\\' => out.push('\\'),
223	                    '/' => out.push('/'),
224	                    'b' => out.push('\u{0008}'),
225	                    'f' => out.push('\u{000c}'),
226	                    'n' => out.push('\n'),
227	                    'r' => out.push('\r'),
228	                    't' => out.push('\t'),
229	                    'u' => {
230	                        let hi = self.hex4();
231	                        let c = if (0xD800..=0xDBFF).contains(&hi) {
232	                            assert_eq!(self.bump(), '\\');
233	                            assert_eq!(self.bump(), 'u');
234	                            let lo = self.hex4();
235	                            assert!(
236	                                (0xDC00..=0xDFFF).contains(&lo),
237	                                "bad low surrogate {lo:x}"
238	                            );
239	                            char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
240	                                .expect("bad surrogate pair")
241	                        } else {
242	                            char::from_u32(hi).expect("bad unicode escape")
243	                        };
244	                        out.push(c);
245	                    }
246	                    c => panic!("bad escape \\{c}"),
247	                },
248	                // Raw control bytes must not appear unescaped in JSON text.
249	                c if (c as u32) < 0x20 => panic!("unescaped control character {c:?} in JSON"),
250	                c => out.push(c),
251	            }
252	        }
253	        out
254	    }
255	
256	    fn hex4(&mut self) -> u32 {
257	        let mut v = 0u32;
258	        for _ in 0..4 {
259	            let c = self.bump();
260	            v = v * 16 + c.to_digit(16).unwrap_or_else(|| panic!("bad hex digit {c:?}"));
261	        }
262	        v
263	    }
264	
265	    fn number(&mut self) -> Json {
266	        let start = self.pos;
267	        if self.chars[self.pos] == '-' {
268	            self.pos += 1;
269	        }
270	        while self.pos < self.chars.len() && self.chars[self.pos].is_ascii_digit() {
271	            self.pos += 1;
272	        }
273	        let text: String = self.chars[start..self.pos].iter().collect();
274	        Json::Num(text.parse().unwrap_or_else(|_| panic!("bad number {text}")))
275	    }
276	
277	    fn boolean(&mut self) -> Json {
278	        if self.chars[self.pos] == 't' {
279	            for want in "true".chars() {
280	                self.expect(want);
281	            }
282	            Json::Bool(true)
283	        } else {
284	            for want in "false".chars() {
285	                self.expect(want);
286	            }
287	            Json::Bool(false)
288	        }
289	    }
290	
291	    fn null(&mut self) -> Json {
292	        for want in "null".chars() {
293	            self.expect(want);
294	        }
295	        Json::Null
296	    }
297	}
298	
299	// ---------------------------------------------------------------------------
300	// Record-level assertions shared by every success-path test.
301	// ---------------------------------------------------------------------------
302	
303	#[derive(Debug)]
304	struct Record {
305	    raw: Json,
306	    format: i64,
307	    algorithm: String,
308	    key_id: String,
309	    key_version: i64,
310	    fields: Vec<String>,
311	    tag: String,
312	}
313	
314	/// Parse the sole JSON record on stdout, enforcing the observable contract:
315	/// exactly one line, exactly the six documented keys in documented order,
316	/// format 1, fixed algorithm name, valid version range, 64 lowercase hex tag.
317	fn parse_single_record(stdout: &[u8]) -> Record {
318	    let text = std::str::from_utf8(stdout).expect("stdout must be valid UTF-8");
319	    assert!(text.starts_with('{'), "stdout must start with the JSON object");
320	    let body = text
321	        .strip_suffix('\n')
322	        .expect("stdout must end with exactly one newline");
323	    assert!(!body.is_empty(), "stdout must contain one JSON record");
324	    assert!(!body.contains('\n'), "stdout must contain exactly one line");
325	    assert!(!body.ends_with('\r'), "line must not carry a carriage return");
326	
327	    let raw = Json::parse(body);
328	    let keys: Vec<&str> = raw.as_object().iter().map(|(k, _)| k.as_str()).collect();
329	    assert_eq!(
330	        keys,
331	        vec![
332	            "format",
333	            "algorithm",
334	            "key_id",
335	            "key_version",
336	            "fields",
337	            "tag"
338	        ],
339	        "record field structure must stay compatible"
340	    );
341	
342	    let fields = raw
343	        .get("fields")
344	        .as_array()
345	        .iter()
346	        .map(|v| v.as_str().to_string())
347	        .collect();
348	
349	    let rec = Record {
350	        format: raw.get("format").as_i64(),
351	        algorithm: raw.get("algorithm").as_str().to_string(),
352	        key_id: raw.get("key_id").as_str().to_string(),
353	        key_version: raw.get("key_version").as_i64(),
354	        fields,
355	        tag: raw.get("tag").as_str().to_string(),
356	        raw,
357	    };
358	
359	    assert_eq!(rec.format, 1, "format must always be 1");
360	    assert_eq!(rec.algorithm, "HMAC-SHA256");
361	    assert!(
362	        (1..=u32::MAX as i64).contains(&rec.key_version),
363	        "key_version out of range: {}",
364	        rec.key_version
365	    );
366	    assert_eq!(rec.tag.len(), 64, "tag must be 64 hex characters");
367	    assert!(
368	        rec.tag
369	            .bytes()
370	            .all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')),
371	        "tag must be lowercase hex, got {}",
372	        rec.tag
373	    );
374	    rec
375	}
376	
377	/// Successful invocation: exit code 0, empty stderr, one valid record whose
378	/// fields/key-id/version match the inputs and whose tag equals the golden
379	/// value computed independently of this implementation.
380	fn expect_signed_record(
381	    label: &str,
382	    key: &str,
383	    key_id: &str,
384	    version: &str,
385	    fields: &[&str],
386	    golden_tag: &str,
387	) -> Record {
388	    let out = run_sign(key, key_id, version, fields);
389	    assert_eq!(
390	        out.status.code(),
391	        Some(0),
392	        "{label}: expected exit 0, got {:?}, stderr={:?}",
393	        out.status.code(),
394	        String::from_utf8_lossy(&out.stderr)
395	    );
396	    assert!(
397	        out.stderr.is_empty(),
398	        "{label}: stderr must be empty, got {:?}",
399	        String::from_utf8_lossy(&out.stderr)
400	    );
401	
402	    let rec = parse_single_record(&out.stdout);
403	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
404	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
405	    assert_eq!(
406	        rec.key_version,
407	        version.parse::<i64>().unwrap(),
408	        "{label}: key_version mismatch"
409	    );
410	    assert_eq!(
411	        rec.fields,
412	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
413	        "{label}: parsed fields must be character-identical to the inputs"
414	    );
415	
416	    // The raw key is used only for the MAC: it must never appear as a value
417	    // anywhere in the record (compared as a whole string, not a substring, so
418	    // short keys cannot clash with random fragments of the 64-char tag).
419	    let needle = key.to_lowercase();
420	    let mut strings = Vec::new();
421	    rec.raw.strings(&mut strings);
422	    assert!(
423	        strings.iter().all(|s| s.to_lowercase() != needle),
424	        "{label}: raw key material must not be part of the record"
425	    );
426	    rec
427	}
