431	// ---------------------------------------------------------------------------
432	
433	#[test]
434	fn readme_example_matches_published_record() {
435	    // The exact command and JSON line documented in README.md. The tag is the
436	    // publicly documented value, so this also pins README/implementation drift.
437	    let rec = expect_signed_record(
438	        "readme",
439	        "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b",
440	        "demo",
441	        "3",
442	        &["hello", "世界"],
443	        "e451500f028e969efb0d6fe533ab40a90d2e8267112cd5c95804d86f7f076d8f",
444	    );
445	    assert_eq!(rec.fields, vec!["hello".to_string(), "世界".to_string()]);
446	}
