559	/// Run the same signing twice and return both records' parsed form plus the
560	/// exact stdout bytes, for determinism comparisons.
561	fn sign_twice(key: &str, key_id: &str, version: &str, fields: &[&str]) -> (Record, Record, Vec<u8>, Vec<u8>) {
562	    let out1 = run_sign(key, key_id, version, fields);
563	    let out2 = run_sign(key, key_id, version, fields);
564	    assert_eq!(out1.status.code(), Some(0));
565	    assert_eq!(out2.status.code(), Some(0));
566	    assert!(out1.stderr.is_empty() && out2.stderr.is_empty());
567	    (
568	        parse_single_record(&out1.stdout),
569	        parse_single_record(&out2.stdout),
570	        out1.stdout,
571	        out2.stdout,
572	    )
573	}
